(window.TNQ=window.TNQ||[]).push({"terms":{"구성개념":{"d":"지능, 불안처럼 직접 관찰할 수 없고 이론적으로 정의되어 행동으로 추론하는 심리적 개념이다.","r":[]},"표집된 행동":{"d":"전체 행동 가운데 일부를 뽑아 측정한 행동으로 검사 점수는 이를 바탕으로 합니다.","r":[]},"무선오차":{"d":"우연한 요인으로 예측할 수 없이 발생하여 점수를 높이거나 낮추는 오차이다.","r":[]},"진점수":{"d":"오차가 없다고 가정한 개인의 참된 점수이다.","r":[]},"측정의 표준오차":{"d":"관찰 점수가 진점수 주변에서 흩어지는 정도로, 값이 작을수록 신뢰도가 높다.","r":[]},"반구조화된 면담":{"d":"정해진 질문을 따르되 상황에 맞게 질문을 보태고 바꿀 수 있는 면담 방식입니다.","r":[]},"선행사건":{"d":"행동 직전에 일어나 행동을 불러일으킨 자극이나 상황입니다.","r":[]},"규준적":{"d":"개인을 다른 사람들과 비교해 일반적 법칙으로 이해하려는 접근입니다.","r":["개인 특이적"]},"개인 특이적":{"d":"한 개인의 고유한 특성과 상황을 그 사람 기준으로 이해하려는 접근입니다.","r":["규준적"]},"종합체계":{"d":"엑스너가 기존 로샤 체계들을 통합하여 경험적 근거를 갖추도록 만든 채점·해석 체계이다.","r":[]},"결정인":{"d":"로샤 검사에서 피검자가 잉크 반점의 어떤 속성 때문에 그렇게 반응했는지를 가리킵니다.","r":[]},"심리적 결정론":{"d":"인간의 사고와 행동에는 무의식을 포함한 원인이 있다고 보는 정신분석의 가정이다.","r":[]},"기질적 뇌장애":{"d":"뇌의 구조나 기능의 손상으로 인지와 행동에 문제가 생기는 장애이다.","r":[]},"심리측정":{"d":"심리적 속성에 규칙에 따라 수를 부여하는 절차이다.","r":[]},"심리평가":{"d":"심리검사, 면담, 행동관찰 등으로 모은 자료를 종합해 개인의 심리적 특성을 해석하고 판단하는 과정이다.","r":[]},"심리검사":{"d":"표집된 행동을 표준화된 절차로 측정하여 심리적 구성개념의 개인차를 파악하는 도구이다.","r":[]},"최대수행검사":{"d":"수검자가 최선을 다해 답하게 하는 검사로 정답과 오답이 있으며, 지능검사와 적성검사가 해당한다.","r":[]},"습관적 수행":{"d":"평소 습관적으로 하는 행동 방식을 측정하는 것으로, 성격검사나 흥미검사가 이에 해당하고 정답과 오답이 없다.","r":[]},"투사적 검사":{"d":"모호한 자극에 대한 자유로운 반응에서 무의식적 욕구와 내적 상태를 파악하는 검사로 로샤, TAT, SCT, HTP가 있다.","r":[]},"표준화 검사":{"d":"실시, 채점, 해석의 절차와 조건을 일정하게 정해 두고 규준을 갖춘 검사이다.","r":[]},"검사상황변인":{"d":"검사 장소, 검사자의 태도, 수검자의 상태처럼 검사 결과에 영향을 줄 수 있는 상황 요인이다.","r":[]},"규준":{"d":"검사 점수를 해석하기 위한 기준으로, 대표 집단의 점수 분포를 말한다. 개인의 점수가 집단 내 어디에 위치하는지 보여준다.","r":[]},"정신상태검사":{"d":"면담 중 외모, 감정과 정서, 사고, 판단력과 통찰력 등 수검자의 현재 정신 기능을 관찰해 조직적으로 평가하는 절차이다.","r":[]},"구조화된 면담":{"d":"질문의 내용과 순서가 정해져 있어 평정자 간 일치도가 높고 자료를 수량화하기 쉬운 면담이다.","r":[]},"비구조화된 면담":{"d":"질문 순서와 내용이 정해져 있지 않아 풍부한 정보를 얻을 수 있으나 면담자 간 일치도가 낮은 면담이다.","r":[]},"SCID":{"d":"DSM에 따른 정신장애 진단을 위한 구조화된 임상 면담 도구이다. DSM-5에 맞춰 SCID-5가 제작되었다.","r":[]},"행동평가":{"d":"행동주의에서 출발해 구체적 행동과 상황 요인, 선행사건과 결과의 관련성을 중시하는 평가 방식이다.","r":[]},"이야기식 기록":{"d":"관찰한 행동을 서술형으로 그대로 적는 기록법으로 수량화하기 어렵다.","r":[]},"직면":{"d":"면담에서 수검자의 모순이나 회피하는 부분을 지적해 다루도록 하는 개입이다.","r":[]},"내재화 척도":{"d":"CBCL 등에서 불안, 우울, 위축, 신체증상처럼 내면으로 향하는 문제를 묶은 척도이다.","r":[]},"외현화 척도":{"d":"CBCL 등에서 규칙 위반, 공격행동처럼 겉으로 드러나는 문제행동을 묶은 척도이다.","r":[]},"비율 IQ":{"d":"정신연령을 생활연령으로 나누어 100을 곱해 구하는 지능지수로, 스탠포드-비네 검사에서 쓰였다.","r":[]},"편차 IQ":{"d":"같은 연령 집단 안에서 개인의 상대적 위치를 평균 100을 기준으로 나타낸 지능지수로, 웩슬러 검사가 사용한다.","r":[]},"정신연령":{"d":"지능검사 수행 수준이 몇 살 아동의 평균에 해당하는지를 나타내는 연령으로, 비네-시몽 검사에서 처음 제안되었다.","r":[]},"결정 지능":{"d":"학습과 문화적 경험이 축적되어 형성되는 지능으로, 나이가 들어도 유지되거나 증가할 수 있다.","r":[]},"3계층 모델":{"d":"캐롤이 지능의 구조를 일반요인, 광범위 능력, 협소한 능력의 계층으로 파악한 이론이다.","r":[]},"2요인 이론":{"d":"스피어만이 지능을 일반 요인 g와 특수 요인 s로 설명한 이론이다.","r":[]},"Z 점수":{"d":"원점수에서 평균을 빼고 표준편차로 나눈 표준점수로, 평균 0, 표준편차 1이다.","r":[]},"백분위":{"d":"집단에서 해당 점수 이하를 받은 사람의 비율을 백분율로 나타낸 값이다.","r":[]},"신뢰도":{"d":"같은 대상을 반복 측정했을 때 결과가 일관되게 나오는 정도이다.","r":[]},"타당도":{"d":"검사가 측정하려는 것을 실제로 측정하는 정도이다.","r":[]},"예측타당도":{"d":"검사 점수가 미래의 준거 행동을 얼마나 잘 예측하는가를 나타내는 준거타당도의 한 종류이다.","r":[]},"공인타당도":{"d":"검사 점수와 현재 기준이 되는 다른 검사나 준거와의 상관으로 구하는 준거타당도의 한 종류이다.","r":[]},"준거타당도":{"d":"검사 점수와 외부 준거와의 상관으로 타당도를 확인하는 방식으로 예측타당도와 공인타당도를 포함한다.","r":[]},"동형신뢰도":{"d":"같은 내용을 재는 두 개의 동등한 검사 형태의 점수 상관으로 구하는 신뢰도이다.","r":[]},"크론바하 알파":{"d":"문항들이 같은 속성을 일관되게 재는 정도를 나타내는 내적 일관성 신뢰도 계수이다.","r":[]},"유의하다":{"d":"표본에서 나타난 결과가 우연으로 생겼다고 보기 어려워, 정해 둔 유의수준 α보다 p값이 작은 경우를 뜻한다.","r":[]},"전체지능지수":{"d":"웩슬러 검사에서 지표점수들을 합산해 산출하는 전반적 지능 수준으로 FSIQ라고 한다.","r":[]},"언어이해 지수":{"d":"공통성, 어휘, 상식 같은 소검사로 구성되며 언어적 개념 형성과 이해 능력을 나타내는 지수이다.","r":[]},"처리속도 지수":{"d":"동형찾기, 기호쓰기처럼 시각 정보를 빠르게 처리하는 능력을 나타내는 지수이다.","r":[]},"작업기억 지수":{"d":"숫자, 산수 같은 소검사로 정보를 잠시 보유하며 조작하는 능력을 나타내는 지수이다.","r":[]},"과정 점수":{"d":"소검사 수행 과정에서 나타나는 특정 양상을 별도로 점수화한 값이다.","r":[]},"핵심 소검사":{"d":"지표점수와 전체지능지수 산출에 기본으로 쓰이는 소검사이다.","r":[]},"보충 소검사":{"d":"핵심 소검사를 대체하거나 추가 정보를 얻는 데 쓰는 소검사이다.","r":[]},"기호쓰기":{"d":"기호와 숫자의 짝을 보고 제한 시간 내에 기호를 옮겨 적는 소검사로 처리속도를 측정한다.","r":[]},"동형찾기":{"d":"표적 기호와 같은 것이 반응 기호들 속에 있는지 빠르게 찾는 처리속도 소검사이다.","r":[]},"MMPI-2":{"d":"미네소타 다면적 인성검사 2판으로, 임상척도, 타당도 척도, 내용 척도, 보충 척도로 주요 정신병리를 평가하는 자기보고식 검사이다.","r":[]},"VRIN":{"d":"MMPI-2 타당도 척도로, 문항 내용과 관계없는 무선반응이나 혼란을 탐지한다.","r":[]},"F(B) 척도":{"d":"MMPI-2에서 문항 후반부의 비정상적 반응을 탐지하는 타당도 척도이다.","r":[]},"해리스-링고스":{"d":"MMPI-2 임상척도를 하위 요인으로 나눈 소척도로, 해석을 정교하게 한다.","r":[]},"재구성 임상척도":{"d":"MMPI-2 임상척도의 공통 요인을 제거해 구성한 RC 척도이다.","r":[]},"내용 척도":{"d":"MMPI-2에서 수검자가 스스로 인식하고 직접 호소하는 문제를 측정하기 위해 개발된 척도이다.","r":[]},"보충 척도":{"d":"MMPI-2 기본 척도를 보완해 특정 특성이나 증후군을 평가하는 척도이다.","r":[]},"상승 척도 쌍":{"d":"MMPI-2에서 가장 높은 두 임상척도 조합으로 내담자의 성격과 증상을 해석하는 방식이다.","r":[]},"NEO-PI-R":{"d":"성격 5요인 이론에 따라 신경증, 외향성, 개방성, 호감성, 성실성을 측정하는 성격검사이다.","r":[]},"개방성":{"d":"5요인 중 새로운 경험과 생각, 가치에 호기심이 많고 창조적이며 탐구적인 경향이다.","r":[]},"성실성":{"d":"5요인 중 목표 지향적이고 계획적이며 자기통제와 신중성이 높은 경향이다.","r":[]},"신경증":{"d":"5요인 중 불안, 분노 같은 부정적 정서를 쉽게 경험하는 경향이다.","r":[]},"MBTI":{"d":"융의 심리 유형론에 기초한 선호 지표 검사로 외향-내향, 감각-직관, 사고-감정, 판단-인식을 구분한다.","r":[]},"TCI":{"d":"클로닝거의 모델에 따라 기질 네 차원과 성격 세 차원을 측정하는 검사이다.","r":[]},"PAI":{"d":"성격평가질문지로 임상척도, 치료고려척도, 대인관계척도, 타당도 척도로 구성된다.","r":[]},"치료고려 척도":{"d":"PAI에서 공격성, 자살관념, 스트레스, 비지지, 치료거부 등 치료 계획에 필요한 정보를 주는 척도이다.","r":[]},"로샤":{"d":"잉크반점에 대한 반응을 분석해 지각과 사고, 정서를 평가하는 대표적 투사검사이다.","r":[]},"구조적 요약":{"d":"로샤 종합체계에서 채점 결과를 비율과 지표로 정리한 표이다.","r":[]},"발달질":{"d":"로샤 종합체계에서 반응에 나타난 형태 구체성과 조직화 수준을 채점하는 기호이다.","r":[]},"평범반응":{"d":"로샤에서 많은 사람이 공통으로 보는 반응으로, 카드마다 정해진 반응이 있다.","r":[]},"특수지표":{"d":"로샤 종합체계에서 비논리적 사고, 공격적 운동 등 특이한 언어나 반응 양상을 표시하는 점수이다.","r":[]},"주제통각검사":{"d":"그림 카드를 보고 이야기를 꾸미게 해 욕구, 갈등, 대인관계 역동을 파악하는 투사검사이다. TAT라고도 한다.","r":[]},"문장완성검사":{"d":"미완성 문장을 수검자가 완성하게 하여 태도와 갈등, 자기개념을 파악하는 투사검사이다. SCT라고도 한다.","r":[]},"집-나무-사람":{"d":"집, 나무, 사람을 차례로 그리게 해 성격과 정서를 해석하는 투사적 그림검사이다. HTP라고도 한다.","r":[]},"BGT":{"d":"벤더-게슈탈트 검사로 도형을 모사하게 하여 시각-운동 기능과 기질적 뇌손상 여부를 살피는 검사이다.","r":[]},"K-ABC":{"d":"카우프만 아동용 평가 배터리로, 아동의 인지처리 능력과 습득도를 측정하는 검사이다.","r":[]},"K-SADS":{"d":"아동 및 청소년의 정동장애, 조현병 등을 평가하는 반구조화된 진단 면담 도구이다.","r":[]},"T 점수":{"d":"평균과 표준편차를 정해 변환한 표준점수로, Z 점수에 표준편차를 곱하고 평균을 더해 구한다.","r":[]},"지각-운동 기능":{"d":"눈으로 받아들인 시각 정보를 손의 움직임과 연결해 수행하는 능력으로, BGT로 평가할 수 있다.","r":[]},"필압":{"d":"그림을 그릴 때 연필을 누르는 힘으로, HTP에서 수검자의 에너지 수준을 반영하는 지표로 본다.","r":[]},"욕구-압력 분석법":{"d":"머레이가 TAT 이야기를 주인공의 욕구와 환경 자극의 압력 측면에서 해석하는 방식이다.","r":[]},"주인공":{"d":"TAT 이야기에서 수검자가 동일시하는 중심 인물로, 욕구-압력 분석의 출발점이 된다.","r":[]},"통각":{"d":"객관적 자극에 주관적 경험이 더해져 의미를 부여하는 지각 과정이다. TAT가 이 과정을 이용한다.","r":[]},"공통카드":{"d":"TAT에서 연령이나 성별에 관계없이 모든 수검자에게 적용되는 카드이다.","r":[]},"백지카드":{"d":"TAT에서 아무 그림도 없는 카드로, 수검자가 상상으로 장면을 떠올려 이야기를 만든다.","r":[]},"동일시":{"d":"자신을 타인이나 이야기 속 인물과 같다고 느끼며 그 특성을 받아들이는 심리 기제이다.","r":[]},"투사":{"d":"자신의 내적 욕구, 감정, 갈등을 외부 대상이나 타인에게 돌려 지각하는 심리 기제이다.","r":[]},"비밀보장":{"d":"심리평가에서 알게 된 정보를 수검자 동의 없이 외부에 알리지 않는 윤리 원칙으로, 타인을 해칠 위험이나 학대 의심, 법적 강제 시 예외가 있다.","r":[]},"경험적 접근방식":{"d":"검사 제작에서 이론이 아니라 집단 간 응답 차이를 실증적으로 확인해 문항을 선택하는 방식으로, MMPI가 대표적이다.","r":[]},"사전검사":{"d":"본 검사 전에 소규모 집단에 실시하여 문항과 절차의 문제를 점검하는 검사이다.","r":[]},"검사 규준":{"d":"검사 점수의 해석 기준으로, 표준화 집단의 점수 분포를 정리한 자료이다.","r":[]},"요강":{"d":"검사의 목적, 제작 과정, 실시·채점·해석 방법과 신뢰도·타당도 자료를 정리한 안내서이다.","r":[]},"홀랜드":{"d":"직업 흥미와 성격을 현실형, 탐구형, 예술형, 사회형, 설득형, 관습형의 여섯 유형으로 구분한 직업 이론을 제시한 학자이다.","r":[]}},"notes":{"16개의 소검사로 구성되어 있다":"K-WISC-V는 소검사 16개로 이루어져 있다는 구성 정보입니다.","30개 이상으로 너무 많으면 전체 척도를 신뢰하기 힘들다":"응답하지 않은 문항이 30개를 넘으면 검사 결과를 믿고 해석하기 어렵습니다.","5개의 기본지표와 5개의 추가지표를 산출한다":"기본 지표 다섯 가지 외에 해석을 보완하는 추가 지표 다섯 가지를 더 얻을 수 있습니다.","68%의 확률로 진점수가 놓이는 구간의 범위가 더 넓다":"오차가 크면 진점수가 있다고 믿을 수 있는 범위도 넓어져 점수가 덜 정확합니다.","Binet-Simon 검사에서 처음 제안되었다":"정신연령이라는 개념은 비네와 시몽의 검사에서 처음 나왔습니다.","K-WISC-IV에 없던 새로운 소검사가 3개 추가되었다":"새 판은 이전 판에는 없던 소검사를 세 개 새로 도입했습니다.","SCID(Structured Clinical Interview":"SCID는 DSM 진단을 내리기 위한 임상 면담 도구의 영어 이름 앞부분입니다.","Stanford-Binet 검사에서 도입되었다":"정신연령을 생활연령으로 나누는 비율 IQ는 스탠포드-비네 검사에서 쓰기 시작했습니다.","Wechsler 지능검사에서 사용되었다":"웩슬러 검사는 같은 연령 집단 안의 위치로 환산한 편차 IQ를 사용합니다.","for DSM)는 반구조화된 면담도구이다":"질문 순서와 내용이 정해져 있으면서 필요하면 추가로 물을 수 있는 진단 면담 도구입니다.","값이 작을수록 신뢰도는 높아진다":"표준오차가 작다는 것은 측정이 일관되다는 뜻이어서 신뢰도와 반대 방향으로 움직입니다.","개인 특이적(idiographic) 접근을 더 선호한다":"한 사람의 고유한 행동과 상황을 있는 그대로 이해하는 접근을 더 중시합니다.","객관적 검사에 비해 채점 시 평정자 간 일치도가 낮다":"투사검사는 반응을 해석하는 폭이 커서 채점자마다 점수가 달라지기 쉽습니다.","객관적 자극과 주관적 경험의 상호작용으로 만들어진다고 가정한다":"같은 그림도 보는 사람의 경험과 욕구에 따라 다르게 지각된다는 통각의 정의입니다.","검사 결과의 해석은 심리적 결정론(Psychic Determinism)을 전제한다":"이야기 내용이 우연이 아니라 마음속 원인에서 나온 것으로 보고 해석합니다.","검사문항의 개념적 구조를 통계적으로 평가하여 개발되었다":"PAI는 문항이 재려는 개념을 제대로 반영하는지 통계로 따져 가며 만든 검사입니다.","검사의 실시과정을 표준화함으로써 오차를 감소시킬 수 있다":"실시 방법을 똑같이 맞추면 검사 상황의 차이로 생기는 오차가 줄어듭니다.","검사자가 기록용지에 “Q”라고 기록하며 추가질문을 한다":"모호한 반응에는 기록용지에 Q를 적고 무슨 뜻인지 한 번 더 묻습니다.","검사자간 채점 결과의 일치도가 더 낮다":"투사검사는 같은 반응도 채점자에 따라 다르게 매겨지기 쉽습니다.","검사 자극이 모호하여 수검자의 내적 상태가 투사되기 용이하다":"뚜렷한 정답이 없는 자극을 주면 수검자가 자기 생각과 욕구를 그 속에 담아 반응하게 됩니다.","검사자는 표준화된 검사 절차를 지키는 것이 원칙이다":"누가 해도 조건이 같아야 점수를 비교할 수 있어서 정해진 실시 절차대로 진행합니다.","검사자료의 통합에 유용한 정보를 수집하게 해준다":"면담에서 얻은 배경 정보는 검사 점수를 해석하고 하나로 묶을 때 쓸모가 있습니다.","검사자의 기대가 수검자의 반응 결과에 영향을 미친다":"검사자가 어떤 결과를 기대하면 표정과 말투로 전해져 수검자의 반응을 바꿀 수 있습니다.","검사점수에 오차가 개입될 가능성이 더 높다":"검사 A는 오차가 크기 때문에 얻은 점수가 진짜 능력에서 벗어났을 가능성이 높습니다.","검사제작 과정에서 검사도구로 인한 오차를 최소화하여야 한다":"문항이 애매하거나 도구가 부실하면 오차가 생기므로 만들 때부터 줄여야 합니다.","경험적으로 근거를 가지고 실증되었는가에 초점을 두었다":"종합체계는 이론보다 연구로 확인된 변수만 남기려는 경험적 근거를 중시했습니다.","관찰자나 평정자의 편견으로 오차가 발생할 수 있다":"채점하는 사람의 선입견이 점수에 섞이면 수검자의 실제 특성과 다르게 평가됩니다.","규준적(nomothetic) 접근보다":"행동 평가가 일반 법칙을 찾는 규준적 접근보다 다른 접근을 선호한다는 문장의 앞부분입니다.","기록용지에 “P”라고 작성한 경우는 촉구한 것을 의미한다":"P 표시는 검사자가 아동에게 반응을 이어 가도록 격려하거나 촉구했다는 기록입니다.","기질적 뇌장애로 해석할 수 있는 특정한 반응들이 구체화되어 있다":"뇌 손상을 시사하는 반응이 어떤 모습인지 해석 지침에 미리 정리되어 있습니다.","나무를 그리는 단계에서는 종이를 세로로 제시한다":"집-나무-사람 검사에서 나무는 세로로 긴 모양이어서 종이를 세로 방향으로 줍니다.","냉소적 태도를 가지고 있으며 타인을 신뢰할 수 없고 이기적인 존재라고 생각한다":"이 척도가 높으면 사람들을 믿지 않고 자기 이익만 챙긴다고 냉소적으로 봅니다.","다른 사람을 위협하는 것을 즐긴다":"상대를 겁주는 것에서 만족감을 얻는 성향입니다.","다른 사람을 지배하기 위해 폭력을 사용한다":"상대를 자기 뜻대로 움직이게 하려고 폭력을 수단으로 삼는 성향입니다.","단어추리 소검사는 5판에서 삭제되었다":"이전 판에 있던 단어추리는 5판 구성에서는 빠졌습니다.","두 번으로 나누어 검사를 실시할 수 있다":"검사 분량이 많을 때는 회기를 둘로 나누어 수검자의 피로를 줄일 수 있습니다.","로샤(Rorschach) 검사의 종합체계는 Exner가 고안하였다":"로샤 검사의 여러 방식을 통합한 종합체계를 만든 사람이 엑스너입니다.","머레이(H. Murray) 방식으로 실시하는 경우 두 번의 회기로 나누어 시행한다":"머레이 방식은 한 번에 다 하지 않고 두 회기에 걸쳐 나누어 실시합니다.","면담 시 실시하는 정신상태검사는 지적 기능 영역을 포함한다":"면담 중 정신상태를 살필 때 기억, 주의, 판단 같은 지적 기능도 평가 항목입니다.","무선오차에 의한 분산이 더 크다":"점수가 우연에 의해 흔들리는 폭이 더 커서 반복 측정하면 결과가 크게 달라집니다.","문화적 여건의 영향을 많이 받는다":"언어이해는 어휘와 상식에 기대어 있어 자라난 문화적 환경에 따라 점수가 달라집니다.","반응 수가 지표 계산에 사용된다":"이 범주의 반응이 몇 개인지 세어 지표를 계산합니다.","반응의 영역, 결정인 및 내용을 확인하는 데 초점을 둔다":"질문단계의 목적으로, 반응이 반점의 어느 부분이고 어떤 특징과 내용이었는지 밝히는 일입니다.","법률에 의해 검사가 의뢰된 경우 수검자에게 평가 동의를 받지 않아도 된다":"법원 의뢰처럼 법적 근거로 시행되는 평가는 수검자의 사전 동의가 필수 요건이 아닙니다.","불행하게 느끼며 의기소침하고 미래에 대해 비관적이다":"이 척도가 높으면 즐거움이 낮고 우울하며 앞날을 어둡게 봅니다.","사회적 규범과 기대에 순응하지 않고 타인에게 공격적이며 갈등적인 인간관계를 보인다":"이 척도가 높으면 규칙을 어기고 다른 사람과 부딪히는 일이 잦습니다.","상담 중에 상담자를 통제하려고 노력한다":"상담 상황에서도 주도권을 잡으려 하고 상담자의 말과 행동을 좌우하려 합니다.","상황적 결정 요인을 강조하며 개인차를 중요하게 여긴다":"행동은 상황에 따라 달라진다고 보면서 사람마다 다르다는 점도 평가에 반영합니다.","상황적 요인에 의해 수검자의 반응이 더 영향 받는다":"검사 분위기나 검사자와의 관계 같은 상황에 따라 같은 사람도 다르게 반응할 수 있습니다.","성취욕구는 도판1의 일반적인 주제의 하나이다":"도판 1에서 흔히 나오는 이야기 주제 가운데 하나가 성취욕구라는 내용입니다.","소화 기능 문제, 두통, 신경과적 증상과 같은 다양한 신체증상을 보고한다":"이 척도가 높으면 몸의 여러 불편을 호소하는 경향이 있습니다.","수검자가 지시문을 정확하게 이해할 수 있도록 하여야 한다":"지시를 잘못 알아들으면 실력이 아닌 오해가 점수에 반영되므로 이해했는지 확인합니다.","수검자가 한 말을 그대로 기록하여야 한다":"검사자의 해석을 섞지 않고 수검자의 표현을 원문 그대로 적어야 채점이 정확합니다.","수검자에 기인하는 오차는 그 원인을 통제하기 어렵다":"피로나 기분처럼 수검자 안의 요인은 검사자가 마음대로 조절할 수 없습니다.","수검자의 반응을 기록할 때에는 말한 그대로의 내용을 모두 기록해야 한다":"해석하거나 요약하지 않고 수검자가 한 말을 그대로 적어야 나중에 정확히 채점합니다.","수검자의 연령과 성별에 따라 도판을 선정해야 한다":"모든 도판을 쓰지 않고 수검자에게 맞는 도판만 골라 제시합니다.","수검자의 응답이 문법에 맞지 않다는 이유로":"언어이해 소검사 채점 원칙을 설명하는 문장의 앞부분으로, 문법 오류가 있는 응답을 다룹니다.","수검자의 이야기 속에 의식 및 무의식적 갈등이 표출된다고 가정한다":"주제통각검사는 그림을 보고 지어낸 이야기에 수검자의 갈등이 드러난다고 봅니다.","수집된 다양한 자료를 조직화하여 통합한다":"면담과 검사 등 여러 자료를 따로 두지 않고 하나의 이해로 묶어 서술합니다.","시각-운동 기민성을 측정한다":"기호쓰기는 눈으로 보고 손으로 재빠르게 옮겨 쓰는 능력, 곧 시각과 운동의 협응을 잽니다.","식물, 구름, 지도, 풍경, 자연의 다섯 가지 범주들의":"고립지표를 구하는 데 쓰는 반응 범주를 나열한 문장의 앞부분입니다.","신뢰도와 타당도를 검증하기 더 어렵다":"점수가 일관된지, 재려는 것을 재는지 객관적으로 확인하기가 객관적 검사보다 까다롭습니다.","심리적 구성개념을 측정하기 위한 수단이다":"심리검사는 눈에 보이지 않는 지능이나 성격 같은 개념을 점수로 재려는 도구입니다.","심리적 특성의 개인차를 비교할 수 있다":"같은 방식으로 재면 사람들 사이에 특성이 얼마나 다른지 견줄 수 있습니다.","심리평가의 사유를 확인하는 과정이 포함된다":"면담에서는 왜 평가를 받게 되었는지 의뢰 이유를 먼저 확인합니다.","아동과 성인에게 모두 실시할 수 있다":"이 검사는 연령 제한이 없어서 아이와 어른 모두에게 쓸 수 있습니다.","아동의 반응이 불완전하거나 명료하지 않을 경우":"반응이 모호할 때 검사자가 어떻게 하는지 설명하는 문장의 앞부분입니다.","언어이해 지표의 보충 소검사이다":"이해 소검사는 언어이해 지표의 핵심이 아니라 보충으로 쓰이는 소검사입니다.","언어적 혹은 신체적으로 공격적이다":"말이나 몸으로 다른 사람을 공격하는 행동을 보입니다.","엑스너(J. Exner)는 종합체계 방식을 개발하였다":"엑스너는 로샤 검사의 실시와 채점 방식을 표준화한 종합체계를 만들었습니다.","의뢰 목적에 맞는 검사를 선택하는 것이 바람직하다":"검사를 의뢰한 이유에 답할 수 있는 도구를 골라야 필요한 정보를 얻습니다.","의뢰사유에 대해 명확한 답을 제공한다":"보고서는 왜 평가를 의뢰했는지에 대해 분명한 결론을 주어야 합니다.","작업기억 지표의 보충 소검사이다":"순서화는 작업기억 지표에서 핵심 소검사를 대신하거나 보태는 보충 소검사입니다.","전반적인 성격을 측정하기 위해 실시한다":"이 검사는 특정 문제가 아니라 사람의 성격 전반을 여러 요인으로 나누어 잽니다.","전체 카드 가운데 수검자의 성별과 연령을 고려하여 일부 카드를 선정 하여 실시한다":"주제통각검사 카드는 모두 쓰지 않고 수검자의 성별과 나이에 맞는 카드만 고릅니다.","전체 행동이 아니라 표집된 행동으로 구성된다":"사람의 행동 전부를 볼 수 없어 대표가 될 만한 일부 행동만 뽑아 문항으로 삼습니다.","전통적 행동관찰과 비교하여 특정한 행동과 맥락 변인에 초점을 둔다":"행동 평가는 막연한 인상 대신 정해진 행동과 그것이 나타나는 상황 요소를 겨냥해 관찰합니다.","정신상태 검사는 정신상태 관찰을 조직화하고자":"정신상태검사의 목적을 설명하는 문장의 앞부분으로, 관찰을 체계적으로 정리하려는 데 있습니다.","제한 시간은 없으나, 가능한 빨리 문장을 완성하도록 지시한다":"문장완성검사는 시간제한은 없지만 오래 생각하지 말고 떠오르는 대로 쓰게 합니다.","지각-운동 기능을 평가할 수 있다":"그림을 그리는 과제를 통해 눈으로 보고 손으로 옮기는 지각과 운동의 협응을 알 수 있습니다.","질문단계는 반응의 영역, 결정인 및 내용을 확인하는 데 초점을 두고 진행한다":"로샤 질문단계는 반점 어디를 보았고 무엇 때문에 그렇게 보였으며 무엇인지 묻는 단계입니다.","집-나무-사람 순서로 그리게 한다":"수검자에게 집, 나무, 사람을 이 순서대로 한 장씩 그리도록 합니다.","채점 과정에서 검사자의 주관이 더 개입된다":"반응을 해석하는 기준이 느슨하여 채점하는 사람의 판단이 결과에 더 많이 반영됩니다.","채점을 불리하게 해서는 안 된다":"문법이 틀려도 내용이 맞으면 점수를 깎지 않는 것이 언어이해 소검사의 채점 원칙입니다.","처리속도 지표의 핵심 소검사이다":"기호쓰기는 처리속도 지표를 구성하는 기본 소검사에 속합니다.","첫 단계는 주인공을 찾는 것이다":"욕구-압력 분석은 이야기에서 중심인물을 정한 뒤 그 사람의 욕구와 환경 압력을 살핍니다.","충동통제가 어렵고, 비난에 예민하며, 만성적으로 적대적이다":"반사회성과 편집증 척도가 함께 높을 때 나타나는 특징으로 분노와 의심이 오래 이어집니다.","측정의 표준오차 값이 더 작다":"검사 B는 점수가 진점수 가까이에 모여 있어 측정이 더 정확합니다.","평정자간 일치도를 산출하기 더 어렵다":"비구조화 면담은 질문과 기록 방식이 일정하지 않아 평정자끼리 얼마나 일치하는지 계산하기 힘듭니다.","피면담자와 면담자의 관계형성이 정보 수집에 영향을 미친다":"서로 신뢰가 쌓여야 피면담자가 속사정을 털어놓아 더 많은 정보를 얻을 수 있습니다.","항목별 5점 척도로 평정하는 채점 체계를 갖추었다":"각 항목을 다섯 단계로 매기는 정해진 채점 방식이 있습니다.","행동관찰을 기술할 때에는 수검자의 구체적이고 독특한 인상에 초점을 맞춘다":"추상적 평가 대신 이 수검자만의 구체적 행동과 인상을 적습니다.","행동 면담을 통해 선행사건, 행동, 결과 간의 관련성을 기술한다":"행동 앞의 계기와 행동 뒤의 결과를 물어 세 가지가 어떻게 이어지는지 정리합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
